# Analyze optimal parallel study combinations
# Strategy: Find overlapping or sequential chunil units across different Speaking months

overlap_analysis = []
for i, item1 in enumerate(grammar_mapping):
    for item2 in grammar_mapping[i+1:]:
        if not item1['chunil_units'] or not item2['chunil_units']:
            continue
        if not item1['speaking_month'] or not item2['speaking_month']:
            continue

        # Find overlapping chunil units
        overlap = set(item1['chunil_units']) & set(item2['chunil_units'])
        if overlap:
            overlap_analysis.append({
                'cat1': item1['category'],
                'cat2': item2['category'],
                'month1': item1['speaking_month'],
                'month2': item2['speaking_month'],
                'overlap_units': sorted(overlap),
                'overlap_count': len(overlap)
            })

print("[FINDING] Categories with overlapping chunil units (synergy opportunities):")
for item in sorted(overlap_analysis, key=lambda x: x['overlap_count'], reverse=True)[:5]:
    print(f"  - {item['cat1']} (M{item['month1']}) + {item['cat2']} (M{item['month2']})")
    print(f"    Overlap: Chunil Units {item['overlap_units']} ({item['overlap_count']} units)")
print(f"\n[STAT:n] Total overlapping pairs found: {len(overlap_analysis)}")

# Identify sequential chunil ranges for smooth progression
print("\n[FINDING] Chunil unit progression analysis:")
chunil_sorted = sorted(grammar_mapping, key=lambda x: min(x['chunil_units']) if x['chunil_units'] else 999)
for item in chunil_sorted:
    if item['chunil_units']:
        chunil_range = f"{min(item['chunil_units'])}-{max(item['chunil_units'])}"
        speaking_info = f"M{item['speaking_month']}" if item['speaking_month'] else "N/A"
        print(f"  {chunil_range:8} | {item['category']:20} | Speaking: {speaking_info} | {item['confidence']}")
